package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class MixedNumberFoundationsTest {
 @Test public void allSelectedConditionsUsePublicNumbersAndWrongSlotOnly(){int count=0;for(String id:List.of(MixedNumberFoundations.TO_IMPROPER,MixedNumberFoundations.TO_MIXED,MixedNumberFoundations.SUM))for(int d=2;d<=12;d++)for(int a=1;a<=(id.equals(MixedNumberFoundations.SUM)?d-1:6);a++)for(int b=1;b<d;b++){if(id.equals(MixedNumberFoundations.SUM)&&a+b<=d)continue;Question q=MixedNumberFoundations.question(id,new int[]{a,b,d});int[] expected=id.equals(MixedNumberFoundations.TO_IMPROPER)?new int[]{a*d+b}:id.equals(MixedNumberFoundations.TO_MIXED)?new int[]{a,b}:new int[]{a+b,(a+b)/d,(a+b)%d};List<String> answer=Arrays.stream(expected).mapToObj(Integer::toString).toList();q.answers=new String[]{"999"};q.expression="999";Checker checker=new Checker();assertTrue(checker.check(q,List.of(),answer).correct());for(int i=0;i<answer.size();i++){List<String> wrong=new ArrayList<>(answer);wrong.set(i,""+(expected[i]+1));Checker.Result r=checker.check(q,List.of(),wrong);assertEquals(Checker.Status.WRONG_ANSWER,r.status);assertEquals(i,r.index);}HelpPlan plan=HelpPlan.forQuestion(q);assertEquals(id.equals(MixedNumberFoundations.SUM)?6:id.equals(MixedNumberFoundations.TO_IMPROPER)?5:4,plan.size());assertFalse(plan.canTransfer());assertTrue(plan.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertFalse(FractionInput.available(q));int[] entries=id.equals(MixedNumberFoundations.TO_IMPROPER)?new int[]{a,b,d,a*d,a*d+b}:id.equals(MixedNumberFoundations.TO_MIXED)?new int[]{a*d+b,d,a,b}:new int[]{a,b,d,a+b,(a+b)/d,(a+b)%d};for(int k=0;k<entries.length;k++)assertTrue(plan.step(k).accepts(""+entries[k]));count++;}assertEquals(1012,count);System.out.println("Mixed-number public conditions="+count);}
 @Test public void allThreeTypesSupplyHundredFreshYearFiveQuestions(){for(String id:List.of(MixedNumberFoundations.TO_IMPROPER,MixedNumberFoundations.TO_MIXED,MixedNumberFoundations.SUM)){Generator generator=new Generator(new Random(177));List<String> recent=new ArrayList<>();boolean twelve=false;for(int i=0;i<100;i++){Question q=generator.next(id,recent,false,GlobalCurriculum.limits("england-primary-2021-v1",id,5));assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=MixedNumberFoundations.read(q);assertNotNull(v);twelve|=v[2]==12;}assertTrue(twelve);}}
 @Test public void inputAndMalformedPublicNumbersAreBounded(){Question q=MixedNumberFoundations.question(MixedNumberFoundations.SUM,new int[]{3,4,5});Checker checker=new Checker();assertTrue(checker.check(q,List.of(),List.of("7.0","1","4/2")).correct());assertEquals(2,checker.check(q,List.of(),List.of("7","1","")).index);assertEquals(Checker.Status.INPUT_NEEDED,checker.check(q,List.of(),List.of("7","1","abc")).status);q.prompt=q.prompt.replace("3/5","999999999999999999/5");assertNull(MixedNumberFoundations.read(q));q=MixedNumberFoundations.question(MixedNumberFoundations.SUM,new int[]{3,4,5});q.prompt=q.prompt.replace("□/5 =","□/6 =");assertNull(MixedNumberFoundations.read(q));}
}
